ALTER TABLE tenants ADD COLUMN IF NOT EXISTS billing_enforced boolean NOT NULL DEFAULT false;
ALTER TABLE tenants ADD COLUMN IF NOT EXISTS privacy_email text NOT NULL DEFAULT '';
ALTER TABLE tenants ADD COLUMN IF NOT EXISTS privacy_retention_days integer NOT NULL DEFAULT 365 CHECK(privacy_retention_days BETWEEN 30 AND 3650);
CREATE TABLE platform_admins(user_id text PRIMARY KEY REFERENCES auth_user(id) ON DELETE CASCADE,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE plans(id text PRIMARY KEY,name text NOT NULL CHECK(length(name) BETWEEN 2 AND 80),description text NOT NULL DEFAULT '',monthly_price integer CHECK(monthly_price BETWEEN 0 AND 100000000),max_professionals integer CHECK(max_professionals BETWEEN 1 AND 1000),published boolean NOT NULL DEFAULT false,active boolean NOT NULL DEFAULT true,updated_at timestamptz NOT NULL DEFAULT now(),CHECK(NOT published OR (monthly_price IS NOT NULL AND max_professionals IS NOT NULL)));
INSERT INTO plans(id,name,description) VALUES ('essencial','Essencial','Para começar a organizar a barbearia.'),('equipe','Equipe','Para uma equipe em crescimento.'),('escala','Escala','Para barbearias com equipes maiores.') ON CONFLICT DO NOTHING;
CREATE TABLE subscriptions(tenant_id text PRIMARY KEY REFERENCES tenants(id) ON DELETE CASCADE,plan_id text NOT NULL REFERENCES plans(id),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','active','suspended','cancelled')),price_snapshot integer NOT NULL CHECK(price_snapshot>=0),professional_limit integer NOT NULL CHECK(professional_limit BETWEEN 1 AND 1000),period_end timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(status<>'active' OR period_end IS NOT NULL));
CREATE TABLE subscription_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id text NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,plan_id text NOT NULL REFERENCES plans(id),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','declined')),created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),resolved_at timestamptz);
CREATE UNIQUE INDEX one_pending_plan_request ON subscription_requests(tenant_id) WHERE status='pending';
CREATE TABLE subscription_receipts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id text NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,plan_id text NOT NULL REFERENCES plans(id),amount integer NOT NULL CHECK(amount>=0),method text NOT NULL CHECK(method IN ('Pix','Transferência','Dinheiro','Cortesia')),reference text NOT NULL DEFAULT '',period_end timestamptz NOT NULL,recorded_by text NOT NULL REFERENCES auth_user(id),created_at timestamptz NOT NULL DEFAULT now(),idempotency_key uuid NOT NULL UNIQUE);
CREATE TABLE platform_audit(id bigserial PRIMARY KEY,actor_id text NOT NULL REFERENCES auth_user(id),action text NOT NULL,entity_id text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE legal_acceptances(user_id text NOT NULL REFERENCES auth_user(id) ON DELETE CASCADE,tenant_id text NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,version text NOT NULL,accepted_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,version));
CREATE TABLE privacy_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id text NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,actor_id text NOT NULL,action text NOT NULL,appointment_id uuid,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE operation_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),kind text NOT NULL,status text NOT NULL CHECK(status IN ('running','success','failed')),started_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz,detail text NOT NULL DEFAULT '');
